mapper.select:
SELECT DISTINCT m.`id`, m.`parent_id`, m.`name`, m.`type`, m.`path`, m.`component`, m.`perms`, m.`icon`, m.`sort`, m.`visible`, m.`status`, m.`create_by`, m.`create_time`, m.`update_by`, m.`update_time`, m.`deleted` FROM `sys_menu` m INNER JOIN `sys_role_menu` rm ON rm.`menu_id` = m.`id` INNER JOIN `sys_user_role` ur ON ur.`role_id` = rm.`role_id` INNER JOIN `sys_role` r ON r.`id` = ur.`role_id` WHERE ur.`user_id` = #{userId} AND r.`deleted` = 0 AND r.`status` = 1 AND m.`deleted` = 0 AND m.`status` = 1
AND m.`type` IN #{t}
ORDER BY m.`sort`, m.`id`
